--
-- Table structure for table `gps`
--

DROP TABLE IF EXISTS `gps`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `gps` (
  `gpsid` int NOT NULL AUTO_INCREMENT,
  `uid` int DEFAULT NULL,
  `currentTime` datetime DEFAULT NULL,
  `lat` double DEFAULT NULL,
  `lng` double DEFAULT NULL,
  `pid` int DEFAULT NULL,
  `sid` int DEFAULT NULL,
  PRIMARY KEY (`gpsid`),
  KEY `pid` (`pid`),
  KEY `sid` (`sid`),
  KEY `fk_gps_uid_sid` (`uid`,`sid`),
  CONSTRAINT `fk_gps_uid_sid` FOREIGN KEY (`uid`, `sid`) REFERENCES `user` (`uid`, `sid`),
  CONSTRAINT `gps_ibfk_2` FOREIGN KEY (`pid`) REFERENCES `payload` (`pid`)
) ENGINE=InnoDB AUTO_INCREMENT=1680 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

